func newRecorder() *recorderAlias            { return httptest.NewRecorder() }
func ui2JSONUnmarshal(b []byte, v any) error { return json.Unmarshal(b, v) }
func ui2JSONMarshal(v any) ([]byte, error)   { return json.Marshal(v) }

