	view.DOMEngine = "off"
	if l := s.domEngineLabel(); l != "" {
		view.DOMEngine = l
	}
	view.DOMChecks = s.wiredScanner().DOMCapabilityConfigured()
	json.NewEncoder(w).Encode(view)
}

