		Term: resp.Filter.Term, Regex: resp.Filter.Regex, Case: resp.Filter.Case,
		Negate: resp.Filter.Negate, ScopeOnly: resp.Filter.ScopeOnly,
		MimeJoined: strings.Join(resp.Filter.MIME, ", "), FilteredTotal: resp.FilteredTotal,
